-- A story field menu (Start = main_menu «MENÚ PRINCIPAL», Select = map_menu, X / M = rpg_area_map_menu) opened in the
-- INAROGUE save (slot 4, docs/game/modes/inarogue.md §21): it only exists on the story field, which must never be
-- reachable there. The menu goes black at once and the game goes back to the title, which reopens INAROGUE.
-- Other slots: retail.
do
  -- INAROGUE save (slot 4): nothing of the story field (docs/game/modes/inarogue.md §21; rule «no story-mode leaks»).
  -- The story field can only show up in slot 4 by accident (a 5v5 street battle ends on its battle map: the empty pitch
  -- of 2026-09-28 19:04, where Start opened the story «MENÚ PRINCIPAL» and Select the town map). Whenever the field or
  -- one of its menus is reached there, the scene goes straight back to the title (black, no frame of the field): the
  -- title of slot 4 only hosts INAROGUE and reopens it, which then reads the match result (byte 606 = 23).
  -- 2026-09-30 (§28, the won pachanga that stayed «to play»): a match clears the engine's «game data loaded» guard, so
  -- the title after CMND_GAME_RESET reloads slot 4 FROM DISK. Everything the match left only in memory (byte 606 = 23,
  -- the trigger's result bytes 619-621, the players' experience) was lost. The way back now saves slot 4 first (the
  -- retail autosave, retried while another save job runs, like the dock's Back does) and resets only when that save
  -- is done (or after RF.SAVE_CAP steps, so a failing save can never leave the screen black).
  local RF = {
    SLOT = 2087918688,     -- () -> rogueSlot, active, ...
    BUSY = 3324595690,      -- () -> a save / load job is pending (vr-loader saveslots)
    SAVE_WORKING = 1979970074,            -- 0x7603F21A IS_SAVE_WORKING (retail; used when the loader has no BUSY)
    AUTO_SAVE = 3673719958,               -- CMND_SYSTEM_AUTO_SAVE
    SOCCER = 4156639577,                  -- CMND_IS_SOCCER_MODE: a match (its menus included) is running
    EXIST = 264888438,                    -- CMND_IS_EXIST_MENU? (menu object)
    LOG = 3661580131,                     -- CMND_EVT_LOG
    MENUS = {3874253475 --[[title_menu_2]], 937147172 --[[soccer_team_dock_menu]], 1301289148,
             2533083129, 26522013, 91676902 --[[team_dock_common_top_menu]],
             831645521 --[[vs_route_town_vs_team_menu (INAROGUE VS preview)]],
             747772244 --[[vs_route_town_vs_enemy_formation_menu]]},
    SAVE_WAIT = 45,                       -- steps to see the save job start before the request is sent again
    SAVE_TRIES = 3,
    SAVE_CAP = 600,                       -- hard cap of the whole save wait (10 s at 60 fps): reset anyway
    done = false, rogue = nil, sv = nil,
  }

  local function call(cmd, ...)
    local r = table.pack(pcall(funcLuaCommand, cmd, ...))
    if not r[1] then
      return nil
    end
    return table.unpack(r, 2, r.n)
  end

  local function log(...)
    pcall(funcLuaCommand, RF.LOG, "inarogue field", ...)
  end

  function RF.inRogue()
    if RF.rogue == nil then
      local rs, act = call(RF.SLOT)
      RF.rogue = type(rs) == "number" and rs == act
    end
    return RF.rogue
  end

  -- a menu of INAROGUE / the title / the dock is open, or a match runs: not the field
  function RF.busy()
    if call(RF.SOCCER) == true then
      return true
    end
    for _, m in ipairs(RF.MENUS) do
      if call(RF.EXIST, m) == true then
        return true
      end
    end
    return false
  end

  -- a save job runs (the loader's view first; the retail IS_SAVE_WORKING when the loader has no such command)
  function RF.saving()
    local b = call(RF.BUSY)
    if type(b) == "boolean" then
      return b
    end
    return call(RF.SAVE_WORKING) == true
  end

  -- the retail back to the title (rpg_save_menu.BackToTitle / the dock's FadeOutWait), with the screen already black
  function RF.reset()
    pcall(funcLuaCommand, 937976662, true)          -- no press-start screen (the dock's FadeOutWait does this too)
    pcall(funcLuaCommand, 3897105282)
    pcall(funcLuaCommand, 769636339, 0.5)
  end

  -- start the way back: black at once, then the save of slot 4, then the reset (RF.tick, called every Step)
  function RF.back(where)
    if RF.done then
      return
    end
    RF.done = true
    log("story field / menu in the INAROGUE save -> save slot 4, then back to INAROGUE", where)
    pcall(funcLuaCommand, 609722083, 1, 0)
    if type(funcLuaMenuCommand) == "function" then
      pcall(funcLuaMenuCommand, 3479138216, 0)
    end
    RF.sv = {sent = false, seen = false, frames = 0, tries = 0, total = 0}
  end

  -- one step of the save-then-reset sequence; true while it still runs
  function RF.tick()
    local s = RF.sv
    if s == nil then
      return false
    end
    s.total = s.total + 1
    local busy = RF.saving()
    local finished = false
    if s.total >= RF.SAVE_CAP then
      log("save wait cap reached: back to the title anyway", s.tries, s.seen)
      finished = true
    elseif s.sent then
      if busy then
        s.seen = true
      elseif s.seen then
        log("slot 4 saved before the reset", s.tries)
        finished = true
      else
        s.frames = s.frames + 1
        if s.frames >= RF.SAVE_WAIT then
          if s.tries >= RF.SAVE_TRIES then
            log("the save never started: back to the title anyway", s.tries)
            finished = true
          else
            s.sent = false
          end
        end
      end
    elseif not busy then
      s.tries = s.tries + 1
      s.sent, s.seen, s.frames = true, false, 0
      pcall(funcLuaCommand, RF.AUTO_SAVE)
    end
    if finished then
      RF.sv = nil
      RF.reset()
      return false
    end
    return true
  end
  local init = OnInit
  function OnInit(...)
    local r = table.pack(init and init(...))
    if RF.inRogue() then
      RF.back("story field menu (Start / Select / area map)")
    end
    return table.unpack(r, 1, r.n)
  end
  -- the save of slot 4 before the way back (rfl_common, §28): stepped here, then the reset
  local step = Step
  function Step(...)
    local r = table.pack(step and step(...))
    RF.tick()
    return table.unpack(r, 1, r.n)
  end
end
